from pathlib import Path
import re
p=Path('index.html')
s=p.read_text(encoding='utf-8')

def rep(old,new,label):
    global s
    if old not in s:
        raise SystemExit(f'{label}: bloco não encontrado')
    s=s.replace(old,new,1)

css_anchor="""    .admin-pdf-theme-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 12px; }\n"""
css_new=css_anchor+"""    .admin-template-picker { display:grid; gap:10px; }\n    .admin-template-picker-title { font-weight:800; color:var(--text); }\n    .admin-template-options { display:grid; grid-template-columns:repeat(5,minmax(0,1fr)); gap:10px; }\n    .admin-template-card {\n      appearance:none; border:1px solid var(--border); border-radius:13px; background:var(--surface); padding:0; overflow:hidden; cursor:pointer; text-align:left; transition:.16s ease; min-height:116px;\n    }\n    .admin-template-card:hover { transform:translateY(-1px); border-color:var(--gold); }\n    .admin-template-card.is-selected { outline:2px solid var(--gold); outline-offset:1px; border-color:var(--gold); box-shadow:0 0 0 3px color-mix(in srgb,var(--gold) 14%,transparent); }\n    .admin-template-preview { height:70px; padding:9px; display:grid; gap:5px; background:var(--tpl-bg,#eef2f7); }\n    .admin-template-preview .tpl-head { height:16px; border-radius:5px; background:var(--tpl-dark,#132039); position:relative; }\n    .admin-template-preview .tpl-head::after { content:''; position:absolute; left:8px; right:45%; top:5px; height:4px; border-radius:4px; background:var(--tpl-accent,#d4a62a); }\n    .admin-template-preview .tpl-day { height:17px; border:1px solid var(--tpl-line,#b8c3d1); border-radius:5px; background:var(--tpl-surface,#fff); position:relative; }\n    .admin-template-preview .tpl-day::before { content:''; position:absolute; left:0; top:0; bottom:0; width:23%; background:var(--tpl-soft,#edf1f6); border-radius:4px 0 0 4px; }\n    .admin-template-name { display:block; padding:9px 9px 10px; font-size:.76rem; line-height:1.2; font-weight:800; color:var(--text); }\n    .tpl-policial-f { --tpl-bg:#f7eef2; --tpl-dark:#101d3b; --tpl-accent:#e78da6; --tpl-soft:#f8dce5; --tpl-line:#d9a8b6; }\n    .tpl-vest-f { --tpl-bg:#f7f3fb; --tpl-dark:#182553; --tpl-accent:#9a78c8; --tpl-soft:#efe4f7; --tpl-line:#c7acd9; }\n    .tpl-elegante-f { --tpl-bg:#faf3f4; --tpl-dark:#542033; --tpl-accent:#c78b83; --tpl-soft:#f4e0e3; --tpl-line:#d7b0b4; }\n    .tpl-min-f { --tpl-bg:#f7f5f6; --tpl-dark:#33353a; --tpl-accent:#b87989; --tpl-soft:#eee8ea; --tpl-line:#ccc5c8; }\n    .tpl-premium-f { --tpl-bg:#f8f3f8; --tpl-dark:#35194a; --tpl-accent:#d6aa73; --tpl-soft:#eee1ef; --tpl-line:#cdb7cf; }\n    .tpl-policial-m { --tpl-bg:#121416; --tpl-dark:#071121; --tpl-accent:#d4a62a; --tpl-soft:#1d2227; --tpl-surface:#17191b; --tpl-line:#555d64; }\n    .tpl-vest-m { --tpl-bg:#eaf7fd; --tpl-dark:#082560; --tpl-accent:#f47712; --tpl-soft:#d7effb; --tpl-line:#78add3; }\n    .tpl-exec-m { --tpl-bg:#edf2f8; --tpl-dark:#151d2a; --tpl-accent:#5280b6; --tpl-soft:#dce5ef; --tpl-line:#9eafc2; }\n    .tpl-min-m { --tpl-bg:#f3f3f3; --tpl-dark:#22262b; --tpl-accent:#77818b; --tpl-soft:#e6e8ea; --tpl-line:#b7bdc2; }\n    .tpl-premium-m { --tpl-bg:#fbfaf6; --tpl-dark:#17191b; --tpl-accent:#b58222; --tpl-soft:#f0eadc; --tpl-line:#cdbd99; }\n"""
rep(css_anchor,css_new,'css templates')
rep("""      .admin-pdf-theme-grid, .admin-pdf-button-grid { grid-template-columns: 1fr; }\n""","""      .admin-pdf-theme-grid, .admin-pdf-button-grid { grid-template-columns: 1fr; }\n      .admin-template-options { grid-template-columns:repeat(2,minmax(0,1fr)); }\n""",'css mobile templates')

old_html="""        <div class=\"admin-pdf-theme-grid\">\n          <div class=\"field full\">\n            <label for=\"adminPdfTheme\">Modelo visual do PDF</label>\n            <select id=\"adminPdfTheme\">\n              <optgroup label=\"Modelos femininos\">\n                <option value=\"policial_feminino\">Policial Feminino</option>\n                <option value=\"vestibular_feminino\">Vestibular Feminino</option>\n                <option value=\"elegante_feminino\">Elegante Feminino</option>\n                <option value=\"minimalista_feminino\">Minimalista Feminino</option>\n                <option value=\"premium_feminino\">Premium Feminino</option>\n              </optgroup>\n              <optgroup label=\"Modelos masculinos\">\n                <option value=\"policial_masculino\">Policial Masculino</option>\n                <option value=\"vestibular_masculino\">Vestibular Masculino</option>\n                <option value=\"executivo_masculino\">Executivo Masculino</option>\n                <option value=\"minimalista_masculino\">Minimalista Masculino</option>\n                <option value=\"premium_masculino\" selected>Premium Masculino</option>\n              </optgroup>\n            </select>\n          </div>\n        </div>\n"""
new_html="""        <div class=\"admin-template-picker\">\n          <span class=\"admin-template-picker-title\">Escolha o template visual do PDF</span>\n          <select id=\"adminPdfTheme\" hidden aria-hidden=\"true\">\n            <option value=\"policial_feminino\">Policial Feminino</option>\n            <option value=\"vestibular_feminino\">Vestibular Feminino</option>\n            <option value=\"elegante_feminino\">Elegante Feminino</option>\n            <option value=\"minimalista_feminino\">Minimalista Feminino</option>\n            <option value=\"premium_feminino\">Premium Feminino</option>\n            <option value=\"policial_masculino\">Policial Masculino</option>\n            <option value=\"vestibular_masculino\">Vestibular Masculino</option>\n            <option value=\"executivo_masculino\">Executivo Masculino</option>\n            <option value=\"minimalista_masculino\">Minimalista Masculino</option>\n            <option value=\"premium_masculino\" selected>Premium Masculino</option>\n          </select>\n          <div class=\"admin-template-options\" id=\"adminTemplateOptions\">\n            <button type=\"button\" class=\"admin-template-card tpl-policial-f\" data-pdf-theme=\"policial_feminino\"><span class=\"admin-template-preview\"><span class=\"tpl-head\"></span><span class=\"tpl-day\"></span><span class=\"tpl-day\"></span></span><span class=\"admin-template-name\">Policial Feminino</span></button>\n            <button type=\"button\" class=\"admin-template-card tpl-vest-f\" data-pdf-theme=\"vestibular_feminino\"><span class=\"admin-template-preview\"><span class=\"tpl-head\"></span><span class=\"tpl-day\"></span><span class=\"tpl-day\"></span></span><span class=\"admin-template-name\">Vestibular Feminino</span></button>\n            <button type=\"button\" class=\"admin-template-card tpl-elegante-f\" data-pdf-theme=\"elegante_feminino\"><span class=\"admin-template-preview\"><span class=\"tpl-head\"></span><span class=\"tpl-day\"></span><span class=\"tpl-day\"></span></span><span class=\"admin-template-name\">Elegante Feminino</span></button>\n            <button type=\"button\" class=\"admin-template-card tpl-min-f\" data-pdf-theme=\"minimalista_feminino\"><span class=\"admin-template-preview\"><span class=\"tpl-head\"></span><span class=\"tpl-day\"></span><span class=\"tpl-day\"></span></span><span class=\"admin-template-name\">Minimalista Feminino</span></button>\n            <button type=\"button\" class=\"admin-template-card tpl-premium-f\" data-pdf-theme=\"premium_feminino\"><span class=\"admin-template-preview\"><span class=\"tpl-head\"></span><span class=\"tpl-day\"></span><span class=\"tpl-day\"></span></span><span class=\"admin-template-name\">Premium Feminino</span></button>\n            <button type=\"button\" class=\"admin-template-card tpl-policial-m\" data-pdf-theme=\"policial_masculino\"><span class=\"admin-template-preview\"><span class=\"tpl-head\"></span><span class=\"tpl-day\"></span><span class=\"tpl-day\"></span></span><span class=\"admin-template-name\">Policial Masculino</span></button>\n            <button type=\"button\" class=\"admin-template-card tpl-vest-m\" data-pdf-theme=\"vestibular_masculino\"><span class=\"admin-template-preview\"><span class=\"tpl-head\"></span><span class=\"tpl-day\"></span><span class=\"tpl-day\"></span></span><span class=\"admin-template-name\">Vestibular Masculino</span></button>\n            <button type=\"button\" class=\"admin-template-card tpl-exec-m\" data-pdf-theme=\"executivo_masculino\"><span class=\"admin-template-preview\"><span class=\"tpl-head\"></span><span class=\"tpl-day\"></span><span class=\"tpl-day\"></span></span><span class=\"admin-template-name\">Executivo Masculino</span></button>\n            <button type=\"button\" class=\"admin-template-card tpl-min-m\" data-pdf-theme=\"minimalista_masculino\"><span class=\"admin-template-preview\"><span class=\"tpl-head\"></span><span class=\"tpl-day\"></span><span class=\"tpl-day\"></span></span><span class=\"admin-template-name\">Minimalista Masculino</span></button>\n            <button type=\"button\" class=\"admin-template-card tpl-premium-m\" data-pdf-theme=\"premium_masculino\"><span class=\"admin-template-preview\"><span class=\"tpl-head\"></span><span class=\"tpl-day\"></span><span class=\"tpl-day\"></span></span><span class=\"admin-template-name\">Premium Masculino</span></button>\n          </div>\n        </div>\n"""
rep(old_html,new_html,'html template cards')

old_fn="""    function renderAdminPdfSettings(){\n      const note=el('adminPdfThemeNote');\n      const theme=el('adminPdfTheme')?.value||'premium_masculino';\n"""
new_fn="""    function syncAdminPdfThemeCards(){\n      const theme=el('adminPdfTheme')?.value||'premium_masculino';\n      document.querySelectorAll('.admin-template-card[data-pdf-theme]').forEach(card=>{\n        const selected=card.dataset.pdfTheme===theme;\n        card.classList.toggle('is-selected',selected);\n        card.setAttribute('aria-pressed',selected?'true':'false');\n      });\n    }\n\n    function renderAdminPdfSettings(){\n      const note=el('adminPdfThemeNote');\n      const theme=el('adminPdfTheme')?.value||'premium_masculino';\n      syncAdminPdfThemeCards();\n"""
rep(old_fn,new_fn,'sync cards')

event_anchor="""      el('adminPdfTheme').addEventListener('change',()=>{ renderAdminPdfSettings(); saveAdminDraft(); });\n"""
event_new=event_anchor+"""      document.querySelectorAll('.admin-template-card[data-pdf-theme]').forEach(card=>{\n        card.addEventListener('click',()=>{\n          const select=el('adminPdfTheme');\n          if(!select) return;\n          select.value=card.dataset.pdfTheme||'premium_masculino';\n          renderAdminPdfSettings();\n          saveAdminDraft();\n          toast(`Template selecionado: ${ADMIN_PDF_THEME_LABELS[select.value]||'Modelo personalizado'}.`);\n        });\n      });\n"""
rep(event_anchor,event_new,'events template cards')

p.write_text(s,encoding='utf-8')
print('PATCH_V7_OK')
